import numpy as np
import json
from cpmpy import *
from cpmpy.solvers import CPM_ortools

# Input data
locations = [
    (288, 149), (288, 129), (270, 133), (256, 141), (256, 163), (246, 157),
    (236, 169), (228, 169), (228, 148), (220, 164), (212, 172), (204, 159)
]
n = len(locations)

# Compute distance matrix (Euclidean, rounded to nearest integer)
def euclidean(p1, p2):
    return int(round(np.hypot(p1[0] - p2[0], p1[1] - p2[1])))

dist = np.zeros((n, n), dtype=int)
for i in range(n):
    for j in range(n):
        if i != j:
            dist[i, j] = euclidean(locations[i], locations[j])
        else:
            dist[i, j] = 0

# Decision variables: successor of each city
succ = intvar(0, n-1, shape=n)
# Each city has a unique successor (permutation)
model = Model([AllDifferent(succ)])

# No city can be its own successor
model += [succ[i] != i for i in range(n)]

# Subtour elimination (Miller-Tucker-Zemlin formulation)
u = intvar(0, n-1, shape=n)
model += [u[0] == 0]  # Fix the first city
for i in range(1, n):
    for j in range(1, n):
        if i != j:
            model += [u[i] - u[j] + n * (succ[i] == j) <= n-1]

# Objective: minimize total travel distance
total_dist = sum([dist[i, succ[i]] for i in range(n)])
model.minimize(total_dist)

if model.solve():
    solution = {'travel_distance': int(total_dist.value())}
    print(json.dumps(solution))
else:
    print("No solution found.")
