import json
import numpy as np
from cpmpy import *

# Input data
n_boats = 5
n_periods = 4
capacity = [6, 8, 12, 12, 12]
crew_size = [2, 2, 2, 2, 4]

# Variables
is_host = boolvar(shape=n_boats, name="is_host")  # is_host[b] == 1 if boat b is a host

# visits[g,h,p] == 1 if guest boat g visits host h at period p
# Only guest boats can visit, and only host boats can be visited
visits = boolvar(shape=(n_boats, n_boats, n_periods), name="visits")

model = Model()

# 1. A boat cannot visit itself
for b in range(n_boats):
    for p in range(n_periods):
        model += (visits[b, b, p] == 0)

# 2. Only host boats can be visited
for g in range(n_boats):
    for h in range(n_boats):
        for p in range(n_periods):
            model += (visits[g, h, p] <= is_host[h])

# 3. Host boats do not visit anyone
for h in range(n_boats):
    for p in range(n_periods):
        model += (sum(visits[h, :, p]) == 0)

# 4. Each guest boat visits exactly one host per period (if not a host itself)
for g in range(n_boats):
    for p in range(n_periods):
        # If g is a host, it does not visit anyone
        model += (sum(visits[g, :, p]) == (1 - is_host[g]))

# 5. Capacity constraints: For each host h, in each period p, the sum of all crews on board <= capacity
for h in range(n_boats):
    for p in range(n_periods):
        # Host's own crew + sum of guest crews visiting
        total_aboard = crew_size[h] + sum(visits[g, h, p] * crew_size[g] for g in range(n_boats) if g != h)
        model += (total_aboard <= capacity[h])

# 6. A guest cannot visit the same host more than once
for g in range(n_boats):
    for h in range(n_boats):
        if g != h:
            model += (sum(visits[g, h, p] for p in range(n_periods)) <= 1)

# 7. Guest crews cannot meet more than once
# For all pairs of guest boats (g1, g2), count the number of periods where they visit the same host
for g1 in range(n_boats):
    for g2 in range(g1+1, n_boats):
        if g1 != g2:
            meet_count = []
            for p in range(n_periods):
                for h in range(n_boats):
                    meet_count.append(visits[g1, h, p] * visits[g2, h, p])
            model += (sum(meet_count) <= 1)

# 8. Minimize the number of host boats
model.minimize(sum(is_host))

if model.solve():
    # Prepare the visit schedule as a list of (guest, host, period) where visit occurs
    visits_list = []
    for g in range(n_boats):
        for h in range(n_boats):
            for p in range(n_periods):
                if visits[g, h, p].value() == 1:
                    visits_list.append({'guest': g, 'host': h, 'period': p})
    solution = {
        'visits': visits_list,
        'is_host': is_host.value().astype(int).tolist()
    }
    print(json.dumps(solution))
else:
    print("No solution found.")
